begin
HeapEF := 1;
end

begin
AdLib_Error := 0;
ID_string := 'SOUND-DRIVER-AD-LIB';
GetIntVec(SOUND_INTR,DriverIntVec);
DriverSeg := Dword(longint(DriverIntVec)).lo;
DriverOfs := Dword(longint(DriverIntVec)).hi - 23;
no_drv := FALSE;
for i := 1 to 19 do
  if ID_string[i] <> Chr(Mem[DriverSeg:DriverOfs+i]) then no_drv := TRUE;
if no_drv then
  begin
  AdLib_Error := 1;
  DriverSeg := 0;
  end;
DetectSound := DriverSeg;
end

begin
Init_Driver;
WaveForm(ON);
end

begin
bank_ptr := nil;
rol_ptr := nil;
disk_bank := FALSE;
if DetectSound<>0 then InitDriver;
end

begin
r := 0;
i := 0;
repeat
  Inc(i);
  if s1[i] > s2[i] then r := 1
  else if s1[i] < s2[i] then r := -1;
until (r<>0) or (s1[i]=#0);
Str9Cmp := r;
end

begin
if bad_ins > 50 then Exit;
alrdy := FALSE;
for i := 1 to bad_ins do
  if Str9Cmp(ins, bad_ins_list[i])=0 then alrdy := TRUE;
if not alrdy then
  begin
  Inc(bad_ins);
  if bad_ins > 50 then
    bad_ins_list[51] := MOREINS
  else
    for i := 1 to 9 do
      bad_ins_list[bad_ins][i] := ins[i];
  end;
end

begin
MakeInsName(insname);
Lp := 0;
Rp := bank_header.num + 1;
repeat
  Mp := (Rp + Lp) div 2;
  cmp := Str9Cmp(insname,ins_list^[Mp].name);
  if cmp > 0 then
    Lp := Mp
  else
    Rp := Mp;
until (cmp=0) or ((Rp-Lp) = 1);
if cmp=0 then
  FindIns := Mp
else
  begin
  Add_Bad_Ins(insname);
  FindIns := 0;
  end;
end

begin
if n=0 then n := FindIns('PIANO1'#0#0#0);
if n=0 then n := 1;
if ins_list^[n].index = 0 then
  begin
  Inc(num_ins);
  ins_list^[n].index := num_ins;
  if disk_bank then
    begin
    Assign(f,Bank_File_Name);
    Reset(f,1);
    Seek(f,(bank_header.data_offs+ins_list^[n].N*30));
    BlockRead(f,buf,30);
    Close(f);
    for i := 1 to 28 do
      timbres[num_ins][i] := buf[i];
    end
  else
    for i := 1 to 28 do
      timbres[num_ins][i] := ins_data^[ins_list^[n].N].ins[i];
  end;
GetInst := ins_list^[n].index;
end

begin
AdLib_Error := 0;
num_ins := 0;
Bank_File_Name := BankFile;
Assign(f,BankFile);
Reset(f,1);
BlockRead(f,bank_header,SIZBNKH);
if IOResult<>0 then
  begin
  AdLib_Error := 5;
  Exit;
  end;
if bank_header.num > MAXINS then
  begin
  AdLib_Error := 6;
  Exit;
  end;
ins_buf_size := SIZBNKR*bank_header.num;
if bank_ptr<>nil then Release(bank_ptr);
Mark(bank_ptr);
GetMem(ins_list,ins_buf_size);
if ins_list=nil then
  begin
  AdLib_Error := 7;
  goto 700;
  end;
Seek(f,bank_header.name_offs);
BlockRead(f,ins_list^,ins_buf_size);
if IOResult<>0 then goto 800;
ins_buf_size := SIZINSR*bank_header.num;
if (ins_buf_size<=MAXSIZE) and (MemAvail>(ins_buf_size+MAXROLSZ))
    and (MaxAvail>ins_buf_size) then
  begin
  GetMem(ins_data,ins_buf_size);
  Seek(f,bank_header.data_offs);
  BlockRead(f,ins_data^,ins_buf_size);
  if IOResult<>0 then goto 800;
  end
else
  disk_bank := TRUE;
Close(f);
for i := 1 to bank_header.num do
  begin
  MakeInsName(ins_list^[i].name);
  ins_list^[i].index := 0;
  end;
Exit;
800: AdLib_Error := 8;
Release(bank_ptr);
700: Close(f);
end

begin
for i := 1 to bank_header.num do
  begin
  ins_list^[i].index := 0;
  end;
bad_ins := 0;
num_ins := 0;
end

begin
e := b[4];
e := (e shl 1) + (b[3] shr 7);
if e <> 0 then
  begin
  f := b[3] and $7F;
  f := (f shl 8) + b[2];
  f := (f shl 8) + b[1];
  r := f;
  for i := 1 to 23 do
    r := r / 2;
  r := r + 1;
  e := e - 127;
  if e > 0 then
    for i := 1 to e do
      r := r * 2
  else
    for i := e to -1 do
      r := r / 2;
  Float2Real := r;
  end
else
  Float2Real := 0;
end

begin
AdLib_Error := 0;
Clear_Inst;
Assign(f,FileSpec);
Reset(f,1);
if IOResult<>0 then
  begin
  AdLib_Error := 2;
  goto 900;
  end;
f_size := FileSize(f);
nbuf_size := f_size div 2;
if nbuf_size>MAXSIZE then
  begin
  AdLib_Error := 3;
  goto 900;
  end;
if rol_ptr<>nil then Release(rol_ptr);
Mark(rol_ptr);
GetMem(NoteP,nbuf_size);
if NoteP=nil then goto 700;
GetMem(NoteL,nbuf_size);
if NoteL=nil then goto 700;
GetMem(NoteT,nbuf_size);
if NoteT=nil then goto 700;
GetMem(NoteV,nbuf_size);
if NoteV=nil then goto 700;
n_ptr := 1;
v_ptr := 1;
InitBuf;
if AdLib_Error=8 then goto 900;
if File_buf=nil then goto 700;
SkipBytes(44);
TPB := WordRead;
BPM := WordRead;
SkipBytes(5);
Drums := 1 - ByteRead;
SkipBytes(143);
Tempo := TempoRead;
n := WordRead;
for i := 1 to n do
  begin
  NoteT^[v_ptr] := WordRead;
  FloatRead(NoteV^[v_ptr]);
  Inc(v_ptr);
  end;
NoteT^[v_ptr] := NOTE_END;
Inc(v_ptr);
for v := 0 to 10 do
  begin
  SkipBytes(15);
  etim[v] := WordRead;
  n := 0;
  while (n < etim[v]) do
    begin
    NoteP^[n_ptr] := WordRead;
    NoteL^[n_ptr] := WordRead;
    n := n + NoteL^[n_ptr];
    Inc(n_ptr);
    end;
  indx0[v] := n_ptr;
  SkipBytes(15);
  idxI0[v] := v_ptr;
  n := WordRead;
  for i := 1 to n do
    begin
    NoteT^[v_ptr] := WordRead;
    InstRead(NoteV^[v_ptr]);
    if etim[v] <> 0 then Inc(v_ptr);
    end;
  NoteT^[v_ptr] := NOTE_END;
  Inc(v_ptr);
  SkipBytes(15);
  idxV0[v] := v_ptr;
  n := WordRead;
  for i := 1 to n do
    begin
    NoteT^[v_ptr] := WordRead;
    FloatRead(NoteV^[v_ptr]);
    Inc(v_ptr);
    end;
  if (etim[v]=0) and (n>0) then Dec(v_ptr);
  NoteT^[v_ptr] := NOTE_END;
  Inc(v_ptr);
  SkipBytes(15);
  idxP0[v] := v_ptr;
  n := WordRead;
  for i := 1 to n do
    begin
    NoteT^[v_ptr] := WordRead;
    FloatRead(NoteV^[v_ptr]);
    Inc(v_ptr);
    end;
  if (etim[v]=0) and (n>0) then Dec(v_ptr);
  NoteT^[v_ptr] := NOTE_END;
  Inc(v_ptr);
  end;
Close(f);
Exit;
700: AdLib_Error := 7;
900: Close(f);
Release(rol_ptr);
end

begin
  n := f_size - FilePos(f);
  if n < Fbuf_size then
    BlockRead(f,File_buf^,n)
  else
    BlockRead(f,File_buf^,Fbuf_size);
  if IOResult<>0 then AdLib_Error := 8;
  end

begin
  if f_size < MAXSIZE then
    Fbuf_size := f_size
  else
    Fbuf_size := MAXSIZE;
  if (MemAvail<(f_size+Fbuf_size)) or (MaxAvail<Fbuf_size) then
    Fbuf_size := 256;
  GetMem(File_buf,Fbuf_size);
  if File_buf=nil then Exit;
  Block_Read;
  Buf_ptr := 1;
  end

begin
  if Buf_ptr > Fbuf_size then
    begin
    Block_Read;
    Buf_ptr := Buf_ptr - Fbuf_size;
    end;
  end

begin
  Buf_ptr := Buf_ptr + nb;
  CheckBuf;
  end

begin
  ByteRead := File_buf^[Buf_ptr];
  Inc(Buf_ptr);
  CheckBuf;
  end

begin
  b1 := ByteRead;
  b2 := ByteRead;
  WordRead := b1 + b2*256;
  end

begin
  b[1] := ByteRead;
  b[2] := ByteRead;
  b[3] := ByteRead;
  b[4] := ByteRead;
  TempoRead := Float2Real(b);
  end

begin
  b[1] := ByteRead;
  b[2] := ByteRead;
  b[3] := ByteRead;
  b[4] := ByteRead;
  end

begin
  for i := 1 to 9 do
    s[i] := Chr(ByteRead);
  n := GetInst(FindIns(s));
  b[1] := Lo(n);
  b[2] := Hi(n);
  SkipBytes(1);
  b[3] := ByteRead;
  b[4] := ByteRead;
  end

begin
time := 0.0;
Etik := 0;
Ltik := 0;
for i := 0 to 10 do
  if etim[i] > Ltik then Ltik := etim[i];
i := 1;
repeat
  Inc(i);
  if NoteT^[i]<Ltik then
    begin
    time := time+(NoteT^[i]-NoteT^[i-1])*60.0/TPB/Float2Real(NoteV^[i-1])/Tempo;
    Etik := NoteT^[i];
    end
  else
    NoteT^[i] := NOTE_END;
until NoteT^[i]=NOTE_END;
EstimTime := Round(time+(Ltik-Etik)*60.0/TPB/Float2Real(NoteV^[i-1])/Tempo);
end

begin
PlayState(OFF);
SoundOff;
end

begin
AdLib_Error := 0;
InitDriver;
DrumMode(Drums);
SetTPB(TPB);
SetStartTime(TPB,0);
play := FALSE;
rdy := TRUE;
cnt := 0;
idxT := 1;
indx[0] := 1;
for v := 0 to 10 do
  begin
  if etim[v] = 0 then
    ptim[v] := NOTE_END
  else
    ptim[v] := 0;
  if v > 0 then indx[v] := indx0[v-1];
  idxI[v] := idxI0[v];
  idxV[v] := idxV0[v];
  idxP[v] := idxP0[v];
  end;
QuitPlay := FALSE;
ctim := 0;
repeat
  mtim := NOTE_END;
  if (NoteT^[idxT]=ctim) and (ctim<NOTE_END) then
    begin
    SetTempo(TPB,ctim,Round(Float2Real(NoteV^[idxT])*Tempo));
    if Snd_Buf_Stat<>0 then Inc(idxT);
    if rdy then Inc(cnt);
    end;
  if mtim > NoteT^[idxT] then mtim := NoteT^[idxT];
  for v := 0 to 10 do
    if ctim<=etim[v] then
      begin
      ActiveVoice(v);
      if NoteT^[idxI[v]] = ctim then
        begin
        SetTimbre(TPB,ctim,@timbres[InstNum(NoteV^[idxI[v]])]);
        if Snd_Buf_Stat<>0 then Inc(idxI[v]);
        if rdy then Inc(cnt);
        end;
      if mtim > NoteT^[idxI[v]] then mtim := NoteT^[idxI[v]];
      if NoteT^[idxV[v]] = ctim then
        begin
        n := Round(100*Float2Real(NoteV^[idxV[v]]));
        SetVolume(TPB,ctim,100,n);
        if rdy and (n<>0) then play := TRUE;
        if Snd_Buf_Stat<>0 then Inc(idxV[v]);
        if rdy then Inc(cnt);
        end;
      if mtim > NoteT^[idxV[v]] then mtim := NoteT^[idxV[v]];
      if NoteT^[idxP[v]] = ctim then
        begin
        SetPitch(TPB,ctim,100,Round(100*Float2Real(NoteV^[idxP[v]]))-100,0);
        if Snd_Buf_Stat<>0 then Inc(idxP[v]);
        if rdy then Inc(cnt);
        end;
      if mtim > NoteT^[idxP[v]] then mtim := NoteT^[idxP[v]];
      if ptim[v] = ctim then
        begin
        if (NoteP^[indx[v]]=0) or (rdy and (not play)) then
          PutNoteDelay(TPB,NoteL^[indx[v]],TPB,0,0)
        else
          PutNote(TPB,NoteL^[indx[v]],NoteP^[indx[v]]-60);
        if Snd_Buf_Stat<>0 then
          begin
          ptim[v] := ptim[v] + NoteL^[indx[v]];
          Inc(indx[v]);
          if ptim[v] >= etim[v] then
            ptim[v] := NOTE_END;
          end;
        if rdy then Inc(cnt);
        end;
      if mtim > ptim[v] then mtim := ptim[v];
      end;
  if play and ((cnt>200) or (mtim=NOTE_END)) then
    begin
    if Snd_Buf_Stat=0 then
      begin
      AdLib_Error := 4;
      Exit;
      end;
    PlayState(ON);
    rdy := FALSE;
    play := FALSE;
    end;
  ctim := mtim;
  Keybd;
until QuitPlay  or ((ctim=NOTE_END) and (GetState=OFF));
PlayOff;
end

begin
  InstNum := b[1]+b[2]*256;
  end

begin
if status=ON then
  begin
  PlayState(OFF);
  for v := 0 to 10 do
    DirectNoteOff(v);
  end
else
  PlayState(ON);
end

begin
HeapError := @HeapEF;
end

begin
   plus := enemy[foe].E_number;
   plus := plus * plus * plus div 8;
   if plus = 0 then plus := 1;
   if not enemy[foe].unconscious then begin
      str(plus,s);
      cPrint(14,11,player[person].name+'는 ',s,'만큼 경험치를 얻었다 !');
      with player[person] do experience := experience + plus;
   end
   else begin
      for i := 1 to 6 do if exist(i) then
      player[i].experience := player[i].experience + plus;
   end;
end

begin
   if party.etc[6] = 2 then exit;
   long := 0;
   for i := 1 to enemynumber do begin
      j := enemy[i].E_number;
      k := enemydata[j].ac;
      if k = 0 then k := 1;
      with enemydata[j] do begin
         plus := level;
         plus := plus * level;
         plus := plus * level;
         plus := plus * k;
         long := long + plus;
      end;
   end;
   party.gold := party.gold + long;
   str(long,s);
   message(15,'일행은 '+s+'개의 금을 얻었다.');
end

begin
   if clean then begin
      SetFillStyle(1,0);
      Bar(20,20,199,199);
      SetFillStyle(1,8);
   end;
   for i:= 1 to enemynumber do
   with enemy[i] do begin
      case hp of
         0 : SetColor(8);
         1..19 : SetColor(12);
         20..49 : SetColor(4);
         50..99 : SetColor(6);
         100..199 : SetColor(14);
         200..299 : SetColor(2)
         else SetColor(10);
      end;
      if unconscious then SetColor(8);
      if dead then SetColor(0);
      OutTextXY(50,20*i+20,name);
   end;
end

begin
   j := 0;
   for i := 1 to enemynumber do
   if not enemy[i].dead then inc(j);
   if j = 0 then ExistEnemies := FALSE else ExistEnemies := TRUE;
end

begin
   returnsexdata;
   k := battle[person,3];
   if enemy[k].dead then begin
      if not ExistEnemies then exit;
      battle[person,3] := battle[person,3] + 1;
      k := k + 1;
      if battle[person,3] <= enemynumber then AttackOne;
      exit;
   end;
   s := ReturnMessage(person,battle[person,1],person,battle[person,3]);
   Print(15,s);
   if enemy[k].unconscious and not enemy[k].dead then begin
      case random(4) of
         0 : Print(12,sexdata+'의 무기가 '+enemy[k].name+'의 심장을 꿰뚫었다');
         1 : Print(12,enemy[k].name+'의 머리는 '+sexdata+'의 공격으로 산산 조각이 났다');
         2 : Print(12,'적의 피가 사방에 뿌려졌다');
         3 : Print(12,'적은 비명과 함께 찢겨 나갔다');
      end;
      if soundon then scream2;
      PlusExperience(person,k);
      enemy[k].hp := 0;
      enemy[k].dead := TRUE;
      exit;
   end;
   if (random(20) > player[person].accuracy[1]) then begin
      Print(7,sexdata+'의 공격은 빗나갔다 ....');
      exit;
   end;
   with player[person] do i := round(strength * wea_power * level[1] div 20);
   i := i - i * random(50) div 100;
   if random(100) < enemy[k].resistance then begin
      Print(7,'적은 '+sexdata+'의 공격을 저지했다');
      exit;
   end;
   with enemy[k] do j := round(ac * level * (random(10)+1) / 10);
   i := i - j;
   if i <= 0 then begin
      Print(7,'그러나, 적은 '+sexdata+'의 공격을 막았다');
      exit;
   end;
   with enemy[k] do begin
      hp := hp - i;
      str(i,s);
      if hp <= 0 then begin
         hp := 0;
         unconscious := FALSE; dead := FALSE;
         Print(12,'적은 '+sexdata+'의 공격으로 의식불명이 되었다');
         if soundon then hit;
         PlusExperience(person,k);
         unconscious := TRUE;
      end
      else begin
         cPrint(7,15,'적은 ',s,'만큼의 피해를 입었다');
         if soundon then hit;
      end;
      DisplayEnemies(FALSE);
   end;
end

begin
   returnsexdata;
   j := battle[person,2];
   k := battle[person,3];
   if enemy[k].dead then begin
      if not ExistEnemies then exit;
      battle[person,3] := battle[person,3] + 1;
      k := k + 1;
      if battle[person,3] <= enemynumber then castone;
      exit;
   end;
   s := ReturnMessage(person,battle[person,1],battle[person,2],battle[person,3]);
   Print(15,s);
   if enemy[k].unconscious then begin
      Print(12,sexdata+'의 마법은 적의 시체 위에서 작열했다');
      if soundon then scream1;
      PlusExperience(person,k);
      enemy[k].hp := 0;
      enemy[k].dead := TRUE;
      DisplayEnemies(FALSE);
      exit;
   end;
   with player[person] do begin
      i := round(level[2]*j*j/2);
      if sp < i then begin
         Print(7,'마법 지수가 부족했다');
         exit;
      end;
      sp := sp - i;
      if random(20) >= accuracy[2] then begin
         Print(7,'그러나, '+enemy[k].name+'를 빗나갔다');
         exit;
      end;
      i := round(j * j * level[2] * 2);
   end;
   if random(100) < enemy[k].resistance then begin
      Print(7,enemy[k].name+'는 '+sexdata+'의 마법을 저지했다');
      exit;
   end;
   with enemy[k] do j := round(ac * level * (random(10)+1) / 10);
   i := i - j;
   if i <= 0 then begin
      Print(7,'그러나, '+enemy[k].name+'는 '+sexdata+'의 마법 공격을 막았다');
      exit;
   end;
   with enemy[k] do begin
      hp := hp - i;
      str(i,s);
      if hp <= 0 then begin
         Print(12,name+'는 '+sexdata+'의 마법에 의해 의식불능이 되었다');
         if soundon then hit;
         PlusExperience(person,k);
         hp := 0;
         unconscious := TRUE;
      end
      else begin
         cPrint(7,15,name+'는 ',s,'만큼의 피해를 입었다');
         if soundon then hit;
      end;
      DisplayEnemies(FALSE);
   end;
end

begin
   battle[person,3] := 1;
   while battle[person,3] <= enemynumber do begin
      CastOne;
      inc(battle[person,3]);
   end;
end

begin
   if party.etc[38] and bit1 = 0 then begin
      Print(7,'당신에게는 아직 능력이 없다.');
      exit;
   end;
   case battle[person,2] of
      1 : with enemy[battle[person,3]] do begin
             if player[person].sp < 10 then begin
                Print(7,'마법 지수가 부족했다');
                exit;
             end;
             player[person].sp := player[person].sp - 10;
             if random(100) < resistance then begin
                Print(7,'적은 독 공격을 저지 했다');
                exit;
             end;
             if random(40) > player[person].accuracy[2] then begin
                Print(7,'독 공격은 빗나갔다');
                exit;
             end;
             Print(4,name+'는 중독 되었다');
             poison := TRUE;
          end;
      2 : with enemy[battle[person,3]] do begin
             if player[person].sp < 30 then begin
                Print(7,'마법 지수가 부족했다');
                exit;
             end;
             player[person].sp := player[person].sp - 30;
             if random(100) < resistance then begin
                Print(7,'기술 무력화 공격은 저지 당했다');
                exit;
             end;
             if random(60) > player[person].accuracy[2] then begin
                Print(7,'기술 무력화 공격은 빗나갔다');
                exit;
             end;
             Print(4,name+'의 특수 공격 능력이 제거되었다');
             special := 0;
          end;
      3 : with enemy[battle[person,3]] do begin
             if player[person].sp < 15 then begin
                Print(7,'마법 지수가 부족했다');
                exit;
             end;
             player[person].sp := player[person].sp - 15;
             if random(100) < resistance then begin
                Print(7,'방어 무력화 공격은 저지 당했다');
                exit;
             end;
             if ac < 5 then j := 40 else j := 25;
             if random(j) > player[person].accuracy[2] then begin
                Print(7,'방어 무력화 공격은 빗나갔다');
                exit;
             end;
             Print(4,name+'의 방어 능력이 저하되었다');
             if (resistance < 31) or (random(2) = 0) then dec(ac)
             else resistance := resistance - 10;
          end;
      4 : with enemy[battle[person,3]] do begin
             if player[person].sp < 20 then begin
                Print(7,'마법 지수가 부족했다');
                exit;
             end;
             player[person].sp := player[person].sp - 20;
             if random(200) < resistance then begin
                Print(7,'능력 저하 공격은 저지 당했다');
                exit;
             end;
             if random(30) > player[person].accuracy[2] then begin
                Print(7,'능력 저하 공격은 빗나갔다');
                exit;
             end;
             Print(4,name+'의 전체적인 능력이 저하되었다');
             if level > 1 then dec(level);
             if resistance > 0 then resistance := resistance - 10
             else resistance := 0;
